parameters.jsCode:
// Drop grants whose id is already in the sheet (and duplicates within this run)
const logged = new Set($('Read Logged Grants').all().map(i => String(i.json.id ?? '')).filter(Boolean));
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const id = String(item.json.id ?? item.json.number ?? '');
  if (!id || logged.has(id) || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: item.json });
}
return out;

