parameters.jsCode:
const grants = $('Keep Only New Grants').all();
const j = v => Array.isArray(v) ? v.join('; ') : (v ?? '');
return $input.all().map((item, i) => {
  const g = grants[i].json;
  const o = item.json.output || {};
  return { json: {
    id: String(g.id), number: g.number, title: g.title, agency: g.agency, status: g.status,
    openDate: g.openDate, closeDate: g.closeDate, awardCeiling: g.awardCeiling ?? '', awardFloor: g.awardFloor ?? '',
    estimatedTotalFunding: g.estimatedTotalFunding ?? '', eligibleApplicants: j(g.eligibleApplicants),
    categories: j(g.categories), url: g.url,
    score: Math.max(0, Math.min(10, Number(o.score) || 0)), reason: o.reason || '',
    loggedAt: $now.toISO(),
  }};
});

